type Field = { key: string; label: string; type?: "text"|"number"|"date"|"time"|"textarea"|"boolean"|"email"; required?: boolean; hint?: string };
type ModuleDef = { key: string; title: string; table: string; description: string; fields: Field[]; display: string[] };
const F=(key:string,label:string,type:Field["type"]="text",required=false,hint?:string):Field=>({key,label,type,required,hint});
const fetchHouseholdRows=async(table:string,householdId:string,columns="*",orderBy?:string,confirmedOnly=false,ascending=false,activeOnly=false)=>{const rows:any[]=[];let offset=0;while(true){let q=(supabase as any).from(table).select(columns).eq("household_id",householdId);if(confirmedOnly)q=q.eq("status","confirmado");if(activeOnly)q=q.eq("archived",false);if(orderBy)q=q.order(orderBy,{ascending}).order("id",{ascending:true});else q=q.order("id",{ascending:true});const {data,error}=await q.range(offset,offset+999);if(error)throw error;const page=data??[];rows.push(...page);if(page.length<1000)break;offset+=1000;}return rows;};

const resolveOperationalAccount=async(householdId:string,destination:"renan"|"leticia"|"mercado_pago")=>{const {data,error}=await (supabase as any).from("accounts").select("id,name,holder,type").eq("household_id",householdId).eq("archived",false);if(error)throw error;const rows=data??[];const norm=(v:any)=>String(v??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();const ranked=rows.map((a:any)=>{const name=norm(a.name),holder=norm(a.holder),type=norm(a.type);let score=0;if(destination==="renan"){if(name.includes("renan"))score=100;else if(holder==="usuario"&&type==="pessoal")score=80;else if(holder==="usuario"&&!/especie|dinheiro|caixa/.test(name))score=50;}if(destination==="leticia"){if(name.includes("leticia"))score=100;else if(holder==="companheira"&&type==="pessoal")score=80;}if(destination==="mercado_pago"){if(name.includes("mercado pago"))score=100;else if(name.includes("nossa conta"))score=95;else if((holder==="conjunto"||holder==="nossa")&&["digital","compartilhado"].includes(type)&&!/especie|dinheiro|caixa/.test(name))score=80;}return {...a,score};}).filter((a:any)=>a.score>0).sort((a:any,b:any)=>b.score-a.score);if(!ranked[0]&&destination==="mercado_pago"){const placeholder=rows.find((a:any)=>norm(a.name).startsWith("pj")||norm(a.holder)==="empresa"||norm(a.type)==="pj");if(placeholder){const {data,error:updateError}=await (supabase as any).from("accounts").update({name:"Mercado Pago — Nossa",holder:"conjunto",type:"digital"}).eq("id",placeholder.id).eq("household_id",householdId).select("id,name,holder,type").single();if(updateError)throw updateError;return data;}}if(!ranked[0])throw new Error(destination==="mercado_pago"?"Cadastre/identifique a conta Mercado Pago — Nossa em Finanças.":"Não encontrei a conta pessoal de "+(destination==="renan"?"Renan":"Leticia")+" em Finanças.");const selected=ranked[0];const expected=destination==="renan"?{name:"Pessoal — Renan",holder:"usuario",type:"pessoal"}:destination==="leticia"?{name:"Pessoal — Leticia",holder:"companheira",type:"pessoal"}:{name:"Mercado Pago — Nossa",holder:"conjunto",type:"digital"};if(selected.name!==expected.name||selected.holder!==expected.holder||selected.type!==expected.type){const {data,error:updateError}=await (supabase as any).from("accounts").update(expected).eq("id",selected.id).eq("household_id",householdId).select("id,name,holder,type").single();if(updateError)throw updateError;return data;}return selected;};
const syncOperationalIncome=async(args:{householdId:string;source:string;sourceId:string;date:string;amount:number;description:string;destination:"renan"|"leticia"|"mercado_pago";category:string})=>{const operation="pv:auto:"+args.source+":"+args.sourceId;const {data:existing,error:findError}=await (supabase as any).from("transactions").select("id").eq("household_id",args.householdId).eq("operation",operation).maybeSingle();if(findError)throw findError;if(!(args.amount>0)){if(existing?.id){const {error}=await (supabase as any).from("transactions").delete().eq("id",existing.id).eq("household_id",args.householdId);if(error)throw error;}return;}const account=await resolveOperationalAccount(args.householdId,args.destination);const holder=args.destination==="renan"?"usuario":args.destination==="leticia"?"companheira":"conjunto";const payload={household_id:args.householdId,date:args.date||dateNow(),amount:Number(args.amount.toFixed(2)),direction:"entrada",description:args.description,category:args.category,account_id:account.id,holder,operation,status:"confirmado",nature:args.source==="99_uber"?"pessoal":"empresarial",notes:"Lançamento automático vinculado à origem "+args.source+" ("+args.sourceId+"). Não duplique manualmente."};const result=existing?.id?await (supabase as any).from("transactions").update(payload).eq("id",existing.id).eq("household_id",args.householdId):await (supabase as any).from("transactions").insert(payload);if(result.error)throw result.error;};
const syncOperationalExpense=async(args:{householdId:string;sourceId:string;date:string;amount:number;description:string;category:string})=>{const costCode:Record<string,string>={"Combustível":"combustivel","Pedágios":"pedagios","Lavagem":"lavagem","Manutenção":"manutencao","Aluguel do veículo":"aluguel","Outros custos":"outros"};const operation="pv:auto:99_uber_cost:"+args.sourceId+":"+(costCode[args.category]||"outros");const {data:existing,error:findError}=await (supabase as any).from("transactions").select("id").eq("household_id",args.householdId).eq("operation",operation).maybeSingle();if(findError)throw findError;if(!(args.amount>0)){if(existing?.id){const {error}=await (supabase as any).from("transactions").delete().eq("id",existing.id).eq("household_id",args.householdId);if(error)throw error;}return;}const account=await resolveOperationalAccount(args.householdId,"renan");const payload={household_id:args.householdId,date:args.date||dateNow(),amount:Number(args.amount.toFixed(2)),direction:"saida",description:args.description,category:args.category,account_id:account.id,holder:"usuario",operation,status:"confirmado",nature:"pessoal",notes:"Lançamento automático vinculado ao turno Uber/99 ("+args.sourceId+"). Não duplique manualmente."};const result=existing?.id?await (supabase as any).from("transactions").update(payload).eq("id",existing.id).eq("household_id",args.householdId):await (supabase as any).from("transactions").insert(payload);if(result.error)throw result.error;};
