 const taskProjectOptions=(projectOptions.data??[]).filter((p:any)=>{if(!scope)return true;const label=String(p.label||"").toUpperCase();const aliases:Record<string,string[]>={"99":["99","UBER","MOBILIDADE"],"MIMORA":["MIMORA","LOJA","ECOMMERCE","E-COMMERCE"],"BEBIDAS":["BEBIDAS","BEBIDA","ESTÁDIO","EVENTO"],"VIDA":["VIDA","PESSOAL","ROTINA","CASA"]};return (aliases[scope]||[scope]).some(a=>label.includes(a));});
 const renderField=(f:any)=><div key={f.key} className={`space-y-1.5 ${f.type==="textarea"?"sm:col-span-2":""}`}>{f.type==="boolean"?<label className="flex items-center gap-2 pt-2 text-sm"><input type="checkbox" checked={Boolean(form[f.key])} onChange={e=>setForm(s=>({...s,[f.key]:e.target.checked}))}/>{f.label}</label>:<><Label htmlFor={f.key}>{f.label}{f.required?" *":""}</Label>{f.type==="textarea"?<Textarea id={f.key} rows={3} value={form[f.key]??""} onChange={e=>setForm(s=>({...s,[f.key]:e.target.value}))}/>:f.key==="project"&&def.table==="tasks"?<select id={f.key} className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={form.node_id??""} onChange={e=>{const p=(projectOptions.data??[]).find((x:any)=>x.id===e.target.value);const general=e.target.value==="__area__";setForm(s=>({...s,node_id:p?.id||null,project:p?.label||(general?(scope==="99"?"99 / Uber":scope==="BEBIDAS"?"Bebidas":scope==="MIMORA"?"MIMORA":"Vida pessoal"):"")}))}}><option value="">Sem vínculo com projeto</option><option value="__area__">Geral desta área ({scope==="99"?"99 / Uber":scope==="BEBIDAS"?"Bebidas":scope==="MIMORA"?"MIMORA":"Vida pessoal"})</option>{taskProjectOptions.map((p:any)=><option key={p.id} value={p.id}>{p.label}</option>)}</select>:fieldOptions(f)?<select id={f.key} className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={form[f.key]??""} onChange={e=>setForm(s=>({...s,[f.key]:e.target.value}))}><option value="">Selecione</option>{fieldOptions(f)!.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:<Input id={f.key} type={f.type==="number"?"number":f.type==="date"?"date":f.type==="time"?"time":f.type==="email"?"email":"text"} list={f.key==="operation"||f.key==="project"?"project-options":undefined} min={f.type==="number"?"0":undefined} step={f.type==="number"?(integerKeys.includes(f.key)?"1":"0.01"):undefined} value={form[f.key]??""} onChange={e=>setForm(s=>({...s,[f.key]:e.target.value}))} required={f.required}/>}</>}</div>;
 const beverageItems=Array.isArray(form.items)?form.items:[];
