function MindMap({householdId}:{householdId:string}){
 const qc=useQueryClient();
 const [expanded,setExpanded]=useState<Record<string,boolean>>({});
 const [formOpen,setFormOpen]=useState(false);
 const [editing,setEditing]=useState<any|null>(null);
 const blank=(parent_id:string|null=null)=>({label:"",parent_id,description:"",objectives:"",status:"planejado",owner:"",due_date:"",metrics:"",risks:"",costs:"",links:"",notes:""});
 const [form,setForm]=useState<any>(blank());
 const q=useQuery({queryKey:["pv","project_nodes",householdId],queryFn:()=>fetchHouseholdRows("project_nodes",householdId,"*","pos_y",false,true,true)});
 const taskQuery=useQuery({queryKey:["pv","tasks_by_project",householdId],queryFn:()=>fetchHouseholdRows("tasks",householdId,"node_id,status","created_at",false,false,true)});
 const nodes=q.data??[];const tasks=taskQuery.data??[];const roots=nodes.filter((n:any)=>!n.parent_id);
 const children=(id:string)=>nodes.filter((n:any)=>n.parent_id===id);
 const begin=(parent_id:string|null=null)=>{setEditing(null);setForm(blank(parent_id));setFormOpen(true);if(parent_id)setExpanded(v=>({...v,[parent_id]:true}));};
 const edit=(node:any)=>{setEditing(node);setForm({...blank(node.parent_id),...node,costs:node.costs??"",due_date:node.due_date??""});setFormOpen(true);};
 const save=useMutation({mutationFn:async()=>{if(!String(form.label||"").trim())throw new Error("Dê um nome ao eixo ou projeto.");const payload:any={household_id:householdId,label:String(form.label).trim(),parent_id:form.parent_id||null,description:form.description||null,objectives:form.objectives||null,status:form.status||"planejado",owner:form.owner||null,due_date:form.due_date||null,metrics:form.metrics||null,risks:form.risks||null,costs:form.costs===""?null:Number(form.costs),links:form.links||null,notes:form.notes||null};const result=editing?.id?await (supabase as any).from("project_nodes").update(payload).eq("id",editing.id).eq("household_id",householdId):await (supabase as any).from("project_nodes").insert(payload);if(result.error)throw result.error;},onSuccess:()=>{toast.success(editing?"Projeto atualizado.":"Projeto criado.");setFormOpen(false);setEditing(null);qc.invalidateQueries({queryKey:["pv","project_nodes",householdId]});qc.invalidateQueries({queryKey:["pv","project_options",householdId]});qc.invalidateQueries({queryKey:["pv"]});},onError:(e:any)=>toast.error(e.message||"Não foi possível salvar o projeto.")});
 const remove=async(node:any)=>{if(!window.confirm("Excluir \""+node.label+"\"? As tarefas vinculadas ficam preservadas, e os subprojetos passam a ser eixos independentes."))return;const {error}=await (supabase as any).from("project_nodes").delete().eq("id",node.id).eq("household_id",householdId);if(error)toast.error(error.message);else{toast.success("Projeto excluído.");qc.invalidateQueries({queryKey:["pv","project_nodes",householdId]});qc.invalidateQueries({queryKey:["pv","project_options",householdId]});qc.invalidateQueries({queryKey:["pv"]});}};
 const render=(node:any,depth=0):any=><div key={node.id} className="space-y-2"><div className="flex items-start gap-2"><button onClick={()=>setExpanded(s=>({...s,[node.id]:!s[node.id]}))} className="mt-2 w-5 shrink-0 text-muted-foreground">{children(node.id).length?(expanded[node.id]===true?"−":"+"):"·"}</button><div className="min-w-0 flex-1 rounded-xl border bg-card p-3 shadow-soft" style={{marginLeft:Math.min(depth*8,40)}}><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0 flex-1"><p className="font-semibold">{node.label}</p>{node.description&&<p className="mt-1 text-xs leading-5 text-muted-foreground">{node.description}</p>}{tasks.some((t:any)=>t.node_id===node.id)&&(()=>{const linked=tasks.filter((t:any)=>t.node_id===node.id);const done=linked.filter((t:any)=>t.status==="done").length;const pct=Math.round(done/linked.length*100);return <div className="mt-3"><div className="mb-1 flex justify-between text-[10px] text-muted-foreground"><span>{done}/{linked.length} ações concluídas</span><strong>{pct}%</strong></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{width:pct+"%"}}/></div></div>})()}{(node.owner||node.due_date||node.costs!==null&&node.costs!==undefined)&&<p className="mt-2 text-[11px] text-muted-foreground">{[node.owner,node.due_date?new Date(node.due_date+"T12:00:00").toLocaleDateString("pt-BR"):null,node.costs!==null&&node.costs!==undefined?brl(node.costs):null].filter(Boolean).join(" · ")}</p>}</div><Badge variant="secondary">{node.status||"planejado"}</Badge></div><div className="mt-3 flex flex-wrap gap-1.5"><Button size="sm" variant="outline" className="h-8" onClick={()=>begin(node.id)}><Plus className="mr-1 h-3.5 w-3.5"/>Subprojeto</Button><Button size="sm" variant="ghost" className="h-8" onClick={()=>edit(node)}><Pencil className="mr-1 h-3.5 w-3.5"/>Editar</Button><Button size="sm" variant="ghost" className="h-8 text-rose-400" onClick={()=>remove(node)}><Trash2 className="mr-1 h-3.5 w-3.5"/>Excluir</Button></div></div></div>{expanded[node.id]===true&&children(node.id).length>0&&<div className="ml-5 space-y-2 border-l-2 border-primary/20 pl-3">{children(node.id).map((c:any)=>render(c,depth+1))}</div>}</div>;
 return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-[.2em] text-primary">Arquitetura estratégica</p><h1 className="mt-1 font-display text-2xl font-bold">Mapa mental do Projeto de Vida</h1><p className="mt-2 text-sm text-muted-foreground">Organize eixos, projetos e subprojetos. Cada item pode ser criado, editado e excluído sem sair do mapa.</p></div><Button onClick={()=>begin(null)}><Plus className="mr-2 h-4 w-4"/>Novo eixo</Button></div>
 {formOpen&&<Card className="border-primary/30 p-4 sm:p-5"><div className="mb-4 flex items-center justify-between gap-3"><div><h2 className="font-semibold">{editing?"Editar projeto":"Novo eixo ou projeto"}</h2><p className="text-xs text-muted-foreground">{form.parent_id?"Este item será criado dentro do eixo selecionado.":"Item de primeiro nível do mapa."}</p></div><Button variant="ghost" size="sm" onClick={()=>{setFormOpen(false);setEditing(null)}}>Fechar</Button></div><form onSubmit={e=>{e.preventDefault();save.mutate()}} className="grid gap-3 sm:grid-cols-2"><div className="space-y-1 sm:col-span-2"><Label>Nome do eixo / projeto *</Label><Input autoFocus value={form.label} onChange={e=>setForm((v:any)=>({...v,label:e.target.value}))} placeholder="Ex.: Estabilidade financeira, MIMORA, 99 / Uber" required/></div><div className="space-y-1 sm:col-span-2"><Label>Descrição</Label><Textarea rows={2} value={form.description} onChange={e=>setForm((v:any)=>({...v,description:e.target.value}))} placeholder="Qual é o resultado que este projeto precisa entregar?"/></div><div className="space-y-1"><Label>Responsável</Label><Input value={form.owner} onChange={e=>setForm((v:any)=>({...v,owner:e.target.value}))} placeholder="Quem conduz?"/></div><div className="space-y-1"><Label>Prazo</Label><Input type="date" value={form.due_date} onChange={e=>setForm((v:any)=>({...v,due_date:e.target.value}))}/></div><div className="space-y-1"><Label>Status</Label><select className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={form.status} onChange={e=>setForm((v:any)=>({...v,status:e.target.value}))}><option value="planejado">Planejado</option><option value="em_andamento">Em andamento</option><option value="bloqueado">Bloqueado</option><option value="concluido">Concluído</option></select></div><div className="space-y-1"><Label>Orçamento / custo previsto (R$)</Label><Input type="number" min="0" step="0.01" value={form.costs} onChange={e=>setForm((v:any)=>({...v,costs:e.target.value}))} placeholder="Opcional"/></div><details className="rounded-xl border p-3 sm:col-span-2"><summary className="cursor-pointer text-sm font-semibold">Planejamento avançado (opcional)</summary><div className="mt-3 grid gap-3 sm:grid-cols-2"><div className="space-y-1"><Label>Objetivos</Label><Textarea rows={2} value={form.objectives} onChange={e=>setForm((v:any)=>({...v,objectives:e.target.value}))}/></div><div className="space-y-1"><Label>Indicadores de sucesso</Label><Textarea rows={2} value={form.metrics} onChange={e=>setForm((v:any)=>({...v,metrics:e.target.value}))}/></div><div className="space-y-1"><Label>Riscos e impedimentos</Label><Textarea rows={2} value={form.risks} onChange={e=>setForm((v:any)=>({...v,risks:e.target.value}))}/></div><div className="space-y-1"><Label>Links e referências</Label><Input value={form.links} onChange={e=>setForm((v:any)=>({...v,links:e.target.value}))}/></div><div className="space-y-1 sm:col-span-2"><Label>Notas</Label><Textarea rows={2} value={form.notes} onChange={e=>setForm((v:any)=>({...v,notes:e.target.value}))}/></div></div></details><div className="flex justify-end gap-2 sm:col-span-2"><Button type="button" variant="outline" onClick={()=>{setFormOpen(false);setEditing(null)}}>Cancelar</Button><Button type="submit" disabled={save.isPending}>{save.isPending?"Salvando…":"Salvar projeto"}</Button></div></form></Card>}
 <Card className="p-4 sm:p-6">{q.isLoading?"Carregando mapa…":q.error?<p className="text-sm text-destructive">{(q.error as Error).message}</p>:roots.length?roots.map((n:any)=>render(n)): <div className="py-6 text-center"><p className="text-sm text-muted-foreground">Comece criando os eixos principais da sua vida. Depois adicione projetos e subprojetos dentro de cada eixo.</p><Button className="mt-3" onClick={()=>begin(null)}><Plus className="mr-2 h-4 w-4"/>Criar primeiro eixo</Button></div>}</Card></div>;
}

function SettingsPanel({householdId,userId,email,role}:{householdId:string;userId:string;email:string|null;role:string}){
 const [invite,setInvite]=useState("");const [busy,setBusy]=useState(false);const qc=useQueryClient();
 const members=useQuery({queryKey:["pv","members",householdId],queryFn:()=>fetchHouseholdRows("household_members",householdId,"email,display_name,role,created_at","created_at")});
 const invites=useQuery({queryKey:["pv","invites",householdId],queryFn:()=>fetchHouseholdRows("household_invites",householdId,"email,accepted_at,created_at","created_at")});
 const send=async(e:React.FormEvent)=>{e.preventDefault();if(role!=="owner")return toast.error("Somente o administrador pode convidar.");setBusy(true);try{const {error}=await (supabase as any).rpc("create_household_invite",{p_email:invite.trim().toLowerCase()});if(error)throw error;toast.success("Convite registrado. A pessoa deve criar a conta usando exatamente este e-mail.");setInvite("");qc.invalidateQueries({queryKey:["pv","invites",householdId]});}catch(err){toast.error((err as Error).message)}finally{setBusy(false)}};
 return <div className="space-y-5"><div><p className="text-[10px] font-semibold uppercase tracking-[.2em] text-primary">Segurança e membros</p><h1 className="mt-1 font-display text-2xl font-bold">Acesso ao espaço</h1><p className="mt-2 text-sm text-muted-foreground">O espaço aceita no máximo duas pessoas. O convite vincula a conta pelo e-mail autenticado.</p></div><Card className="p-5"><h2 className="font-semibold">Sua sessão</h2><p className="mt-2 text-sm text-muted-foreground">{email} · {role==="owner"?"Administrador":"Membro"}</p><p className="mt-1 text-xs text-muted-foreground">ID de usuário: {userId}</p></Card><Card className="p-5"><h2 className="font-semibold">Membros autorizados</h2><div className="mt-3 space-y-2">{(members.data??[]).map((m:any,i:number)=><div key={i} className="flex items-center justify-between rounded-lg bg-muted/60 p-3"><div><p className="text-sm font-medium">{m.display_name||m.email||"Membro"}</p><p className="text-xs text-muted-foreground">{m.email}</p></div><Badge>{m.role}</Badge></div>)}</div></Card>{role==="owner"&&<Card className="p-5"><h2 className="font-semibold">Convidar a segunda pessoa</h2><form onSubmit={send} className="mt-3 flex flex-col gap-2 sm:flex-row"><Input type="email" required placeholder="E-mail da Leticia" value={invite} onChange={e=>setInvite(e.target.value)}/><Button disabled={busy}>{busy?"Registrando…":"Criar convite"}</Button></form><p className="mt-3 text-xs leading-5 text-muted-foreground">O sistema não envia e-mail automaticamente. Depois de registrar, compartilhe o link do painel. A pessoa deve criar a conta com o mesmo e-mail do convite; o vínculo é aceito no primeiro acesso.</p><div className="mt-4 space-y-2">{(invites.data??[]).map((i:any)=><div key={i.email} className="flex justify-between rounded-lg border p-3 text-xs"><span>{i.email}</span><Badge variant="secondary">{i.accepted_at?"Aceito":"Pendente"}</Badge></div>)}</div></Card>}</div>
}
